using System.Collections; using UnityEngine;
public class BossFightPuppetActivation:MonoBehaviour { [SerializeField,Min(0)] private float delayAfterBossFightStarts=10f; [SerializeField] private Health puppetHealth; [SerializeField] private EnemyAttack puppetAttack; [SerializeField] private float attackDamage=10; [SerializeField] private float attackRange=2; [SerializeField] private float attackCooldown=2; [SerializeField] private bool activateOnlyOnce=true; private bool activated; private Coroutine routine;
 private void Awake(){if(puppetHealth==null)puppetHealth=GetComponent<Health>();if(puppetAttack==null)puppetAttack=GetComponent<EnemyAttack>();if(puppetHealth!=null)puppetHealth.enabled=false;if(puppetAttack!=null)puppetAttack.enabled=false;}
 private void Update(){if(activated&&activateOnlyOnce)return;if(routine==null&&GameStateManager.Instance!=null&&GameStateManager.Instance.GetGameMode()==GameStateManager.GameMode.BossFight)routine=StartCoroutine(Activate());}
 private IEnumerator Activate(){yield return new WaitForSeconds(delayAfterBossFightStarts);if(puppetHealth!=null){puppetHealth.enabled=true;puppetHealth.ResetHealth();}if(puppetAttack!=null){puppetAttack.ConfigureAttack(attackDamage,attackRange,attackCooldown);puppetAttack.enabled=true;}activated=true;routine=null;}
 public void ResetPuppetForNextPlay(){activated=false;if(routine!=null)StopCoroutine(routine);routine=null;if(puppetHealth!=null)puppetHealth.enabled=false;if(puppetAttack!=null)puppetAttack.enabled=false;} }
